import {openStrings,noteName} from './music.js';
export function createFretboard(THREE){
 const group=new THREE.Group();group.name='acoustic-fretboard';const strings=[],markers=[],ghosts=[],halos=[];const nut=-3.25,scale=13.2;const fretX=f=>nut+scale*(1-2**(-f/12));const zFor=s=>.6-s*.24;
 function texture(color){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=color;ctx.fillRect(0,0,1024,256);let seed=31;for(let y=0;y<256;y++){seed=(seed*1664525+1013904223)>>>0;ctx.strokeStyle=seed%2?'rgba(245,198,139,.11)':'rgba(30,10,4,.19)';ctx.beginPath();for(let x=0;x<=1024;x+=16){const yy=y+Math.sin(x*.008+y*.3)*1.8;if(x===0)ctx.moveTo(x,yy);else ctx.lineTo(x,yy);}ctx.stroke();}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}
 const ebonyMap=texture('#3e2b25'),sideMap=texture('#955d3d');const ebony=new THREE.MeshPhysicalMaterial({color:0xffffff,map:ebonyMap,bumpMap:ebonyMap,bumpScale:.008,roughness:.28,metalness:.025,clearcoat:.9,clearcoatRoughness:.17});const side=new THREE.MeshPhysicalMaterial({color:0xffffff,map:sideMap,bumpMap:sideMap,bumpScale:.006,roughness:.24,clearcoat:1,clearcoatRoughness:.13});const ivory=new THREE.MeshPhysicalMaterial({color:0xeee2c9,roughness:.24,metalness:.1,clearcoat:.85,iridescence:.26,iridescenceIOR:1.3});const fretMaterial=new THREE.MeshStandardMaterial({color:0xb4ada0,metalness:1,roughness:.16});const gold=new THREE.MeshStandardMaterial({color:0xb08b52,metalness:.8,roughness:.22});
 function mesh(g,m,x=0,y=0,z=0){const n=new THREE.Mesh(g,m);n.position.set(x,y,z);n.castShadow=true;n.receiveShadow=true;group.add(n);return n;}
 const box=(w,h,d,m,x,y,z)=>{const shape=new THREE.Shape();shape.moveTo(-w/2,-d/2);shape.lineTo(w/2,-d/2);shape.lineTo(w/2,d/2);shape.lineTo(-w/2,d/2);shape.closePath();const bevel=Math.min(.012,w*.24,h*.24,d*.24);const geo=new THREE.ExtrudeGeometry(shape,{depth:h,bevelEnabled:true,bevelSize:bevel,bevelThickness:bevel,bevelSegments:3,steps:1});geo.rotateX(-Math.PI/2);geo.translate(0,-h/2,0);return mesh(geo,m,x,y,z);};
 box(8.6,.24,1.49,side,.75,-.12,0);box(8.58,.085,1.43,ebony,.75,.035,0);for(const z of [-.731,.731]){box(8.6,.033,.025,ivory,.75,-.007,z);box(8.6,.007,.011,gold,.75,.013,z);}
 const nutMesh=box(.075,.11,1.48,ivory,nut,.12,0);nutMesh.name='guitar-nut';
 for(let f=1;f<=15;f++){const rod=mesh(new THREE.CylinderGeometry(.017,.017,1.43,14),fretMaterial,fretX(f),.099,0);rod.rotation.x=Math.PI/2;if([3,5,7,9,12,15].includes(f))for(const z of f===12?[-.22,.22]:[0]){const dot=mesh(new THREE.OctahedronGeometry(.05,0),ivory,(fretX(f)+fretX(f-1))/2,.084,z);dot.scale.set(1,.18,1.3);for(const side of [-1,1]){const petal=mesh(new THREE.SphereGeometry(1,12,7),ivory,dot.position.x+side*.067,.083,z);petal.scale.set(.035,.006,.012);petal.rotation.y=side*.55;}}}
 // Cropped soundboard and headstock keep lacquer and wood visible around the fingerboard.
 const soundboard=box(5,.3,3.4,side,7,-.1,0);soundboard.name='cropped-guitar-body';const ring=mesh(new THREE.TorusGeometry(.65,.025,12,100),gold,6,.07,0);ring.rotation.x=-Math.PI/2;
 const head=box(1.55,.16,1.75,side,-4.15,.01,0);head.rotation.y=-.045;
 for(let j=0;j<3;j++)for(const s of [-1,1]){const tuner=mesh(new THREE.CylinderGeometry(.065,.065,.13,18),fretMaterial,-3.65-j*.35,.14,s*.55);const button=mesh(new THREE.SphereGeometry(1,16,8),ivory,-3.65-j*.35,.015,s*.98);button.scale.set(.11,.045,.06);}
 for(let s=0;s<6;s++){
  const radius=.0145-s*.0017;const geo=new THREE.CylinderGeometry(radius,radius,9.5,10,96);geo.rotateZ(Math.PI/2);const base=geo.attributes.position.array.slice();const material=new THREE.MeshPhysicalMaterial({color:s<3?0xc2aa81:0xd0dfe7,metalness:1,roughness:s<3?.27:.2,clearcoat:.85});const wire=mesh(geo,material,.35,.14,zFor(s));wire.name='guitar-string-'+s;strings.push({mesh:wire,base,energy:0,age:0});
  const marker=mesh(new THREE.SphereGeometry(.084,24,12),new THREE.MeshStandardMaterial({color:0xf2c7a5,emissive:0x9e684d,emissiveIntensity:.26,metalness:.18,roughness:.17}),0,.15,zFor(s));marker.scale.y=.6;marker.visible=false;markers.push(marker);const halo=mesh(new THREE.TorusGeometry(.112,.005,8,40),new THREE.MeshBasicMaterial({color:0xf8d4af,transparent:true,opacity:.38,depthWrite:false}),0,.132,zFor(s));halo.rotation.x=-Math.PI/2;halo.visible=false;halos.push(halo);
  const ghost=mesh(new THREE.TorusGeometry(.084,.007,8,36),new THREE.MeshBasicMaterial({color:0xd7c3a3,transparent:true,opacity:.35}),0,.16,zFor(s));ghost.rotation.x=-Math.PI/2;ghost.visible=false;ghosts.push(ghost);
 }
 const boardHit=box(8.1,.005,1.44,new THREE.MeshBasicMaterial({visible:false}),.5,.17,0);boardHit.userData.guitar=true;
 const markerX=f=>f===0?nut-.14:(fretX(f)+fretX(f-1))/2;
 let previous=new Set();
 return {group,width:7.65,fretX,zFor,markerX,hit:boardHit,strings,
  setEvents(events,next=[]){markers.forEach(x=>x.visible=false);halos.forEach(x=>x.visible=false);ghosts.forEach(x=>x.visible=false);const now=new Set();for(const n of events){const s=n[4],f=n[5];if(!Number.isInteger(s))continue;const key=n[0]+':'+s;now.add(key);markers[s].position.x=markerX(f);markers[s].visible=true;halos[s].position.x=markerX(f);halos[s].visible=true;if(!previous.has(key))this.pluck(s);}for(const n of next){if(!Number.isInteger(n[4])||markers[n[4]].visible)continue;ghosts[n[4]].position.x=markerX(n[5]);ghosts[n[4]].visible=true;}previous=now;},
  pluck(s){if(strings[s]){strings[s].energy=1;strings[s].age=0;}},
  update(dt,time,reduced){halos.forEach((h,i)=>{h.scale.setScalar(reduced?1:1+Math.sin(time*.004+i)*.045);});for(const wire of strings){wire.energy*=Math.exp(-dt*5);const a=wire.mesh.geometry.attributes.position;for(let i=0;i<a.count;i++){const x=wire.base[i*3];a.array[i*3+1]=wire.base[i*3+1]+(reduced?0:Math.sin((x+4.75)/9.5*Math.PI)*Math.sin(time*.09+x*3)*wire.energy*.018);}a.needsUpdate=true;}},
  input(point){const string=Math.max(0,Math.min(5,Math.round((.6-point.z)/.24)));let fret=0;if(point.x>nut+.03){fret=1;while(fret<12&&point.x>fretX(fret))fret++;}return {midi:openStrings[string]+fret,string,fret};},
  labels(){const out=[];for(let f=0;f<=12;f++)out.push({x:markerX(f),y:.16,z:-.92,text:String(f),type:'fret'});for(let s=0;s<6;s++)out.push({x:nut-.35,y:.16,z:zFor(s),text:String(6-s),type:'string'});return out;}
 };
}
